# ПРИМЕР 1: Определитель времени суток
# Программа определяет время суток по введённому часу

print('=== ОПРЕДЕЛИТЕЛЬ ВРЕМЕНИ СУТОК ===')
hour = int(input('Который сейчас час? (0-23): '))

if hour < 0 or hour > 23:
    print('Ошибка! Введите час от 0 до 23.')
elif 6 <= hour <= 11:
    print(f'{hour} часов — это утро. Доброе утро!')
elif 12 <= hour <= 17:
    print(f'{hour} часов — это день. Добрый день!')
elif 18 <= hour <= 22:
    print(f'{hour} часов — это вечер. Добрый вечер!')
else:
    print(f'{hour} часов — это ночь. Доброй ночи!')

# ПРИМЕР 3: Проверка на треугольник с классификацией
# Программа проверяет, существует ли треугольник, и определяет его тип

print('=== АНАЛИЗ ТРЕУГОЛЬНИКА ===')
a = float(input('Длина стороны A: '))
b = float(input('Длина стороны B: '))
c = float(input('Длина стороны C: '))

if a <= 0 or b <= 0 or c <= 0:
    print('Ошибка! Стороны должны быть положительными.')
elif (a + b > c) and (a + c > b) and (b + c > a):
    print('Треугольник существует!')
    if a == b == c:
        triangle_type = 'равносторонний'
    elif a == b or b == c or a == c:
        triangle_type = 'равнобедренный'
    else:
        triangle_type = 'разносторонний'
    print(f'Тип треугольника: {triangle_type}')
else:
    print('Треугольник НЕ существует!')

