# EXAMPLE 3: Triangle check with classification
# The program checks if a triangle exists and determines its type

print('=== TRIANGLE ANALYSIS ===')
a = float(input('Side A length: '))
b = float(input('Side B length: '))
c = float(input('Side C length: '))

if a <= 0 or b <= 0 or c <= 0:
    print('Error! Sides must be positive.')
elif (a + b > c) and (a + c > b) and (b + c > a):
    print('Triangle exists!')
    if a == b == c:
        triangle_type = 'equilateral'
    elif a == b or b == c or a == c:
        triangle_type = 'isosceles'
    else:
        triangle_type = 'scalene'
    print(f'Triangle type: {triangle_type}')
else:
    print('Triangle does NOT exist!')

