# ПРИМЕР 1: Калькулятор с параметрами

def add(a, b):
    return a + b

def subtract(a, b):
    return a - b

def multiply(a, b):
    return a * b

def divide(a, b):
    if b != 0:
        return a / b
    else:
        return 'Ошибка!'

def calculate(num1, num2, operation='+'):
    if operation == '+':
        return add(num1, num2)
    elif operation == '-':
        return subtract(num1, num2)
    elif operation == '*':
        return multiply(num1, num2)
    elif operation == '/':
        return divide(num1, num2)
    else:
        return 'Неизвестная операция!'

print(calculate(10, 5))
print(calculate(10, 5, '*'))
print(calculate(operation='/', num2=3, num1=15))

# ПРИМЕР 2: Генератор повторяющегося текста

def repeat_text(text, times=1, separator=' '):
    result = ''
    for i in range(times):
        result += text
        if i < times - 1:
            result += separator
    print(result)

repeat_text('Ха', 3)
repeat_text('Ура', times=5, separator='! ')

